from rdkit import Chem
rw=Chem.RWMol(Chem.AddHs(Chem.MolFromSmiles('CC1(C)c2cccc(P(c3ccccc3)c3ccccc3)c2Oc2c(P(c3ccccc3)c3ccccc3)cccc21')))
p=[a.GetIdx() for a in rw.GetAtoms() if a.GetSymbol()=='P']
pd=rw.AddAtom(Chem.Atom('Pd'))
for i in p: rw.AddBond(pd,i,Chem.BondType.SINGLE)
# add cycloheptatriene ring, 7 atoms, alternation
cs=[rw.AddAtom(Chem.Atom('C')) for _ in range(7)]
for i in range(7): rw.AddBond(cs[i],cs[(i+1)%7],Chem.BondType.DOUBLE if i%2==0 else Chem.BondType.SINGLE)
for i in [0,1]: rw.AddBond(pd,cs[i],Chem.BondType.SINGLE)
